const need=(el,ok,msg,m)=>{el.setAttribute("aria-invalid",ok?"false":"true");if(!ok){$(m).className="msg";$(m).textContent=msg;el.focus()}return ok};
const info=async()=>{if(INFO.turnstile===undefined){const r=await api("/info");if(r.ok)INFO=r.d}};
function captcha(sel){const go=()=>{CF="";window.turnstile.render(sel,{sitekey:INFO.turnstile,theme:document.documentElement.dataset.theme==="light"?"light":"dark",callback:x=>{CF=x},"expired-callback":()=>{CF=""},"error-callback":()=>{CF=""}})};if(window.turnstile)return go();let s=document.getElementById("tsjs");if(s)return s.addEventListener("load",go);s=document.createElement("script");s.id="tsjs";s.src="https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit";s.async=true;s.onload=go;document.head.appendChild(s)}
const resetCaptcha=sel=>{CF="";if(window.turnstile&&$(sel))turnstile.reset(sel)};
