function ui(){const d=document.documentElement.dataset.theme!=="light";
 $("#ft").innerHTML=foot();
 document.querySelectorAll(".js-theme").forEach(b=>{b.querySelector(".e").innerHTML=ic(d?"tema_claro":"tema_oscuro");b.querySelector(".lbl").textContent=t(d?"Modo claro":"Modo oscuro");b.setAttribute("aria-label",t(d?"Modo claro":"Modo oscuro"))});
 document.querySelectorAll(".js-lang").forEach(b=>{b.querySelector(".e").innerHTML=ic("idioma");b.querySelector(".lbl").textContent=L==="en"?"Español":"English";b.setAttribute("aria-label",L==="en"?"Español":"English")});
 document.querySelector('meta[name="theme-color"]').content=d?"#0e0a0c":"#f8f3f4";$("#up").setAttribute("aria-label",t("Volver arriba"));$("#off").textContent=t("Sin conexión. Algunas cosas no cargarán.");$(".skip").textContent=t("Saltar al contenido");
 document.querySelectorAll("[data-t]").forEach(e=>{e.dataset.o=e.dataset.o||e.innerHTML;e.innerHTML=t(e.dataset.o)})}
function tema(){const r=document.documentElement,n=r.dataset.theme==="light"?"dark":"light";r.dataset.theme=n;try{localStorage.setItem("theme",n)}catch{}ui()}
function idioma(){L=L==="en"?"es":"en";try{localStorage.setItem("lang",L)}catch{}document.documentElement.lang=L;nav();bar();ui();show(view)}
document.addEventListener("click",e=>{if(e.target.closest("[data-soon]")){e.preventDefault();toast(t("Próximamente"))}else if(e.target.closest(".js-theme"))tema();else if(e.target.closest(".js-lang"))idioma()});
const tg=c=>`<button class="btn s ${c}" type="button"><span class="e"></span><span class="lbl"></span></button>`;
function foot(){return `<div class="soc"><a class="btn s" href="${DISCORD}" target="_blank" rel="noopener">${ic("discord_comentarios")} Discord</a><a class="btn s" href="${TIKTOK}" target="_blank" rel="noopener">${ic("tiktok")} TikTok</a></div><div class="soc">${tg("js-theme")}${tg("js-lang")}</div><p>© SampCity RolePlay · ${t("Comunidad no oficial de Rockstar Games / SA-MP")}</p>`}
function fbNav(){document.getElementById("fbt")?.remove();document.body.classList.toggle("has-nav",!!U);if(!U)return;const T=[["/","inicio","Inicio"],["/videos","videos","Videos"],["/marketplace","marketplace","Marketplace"],["/noticias","noticias","Noticias"],["/actualizaciones","actualizaciones","Actualizaciones"]],soon=["/videos","/marketplace"],pa=location.pathname.replace(/\.html$/,"")||"/",on=x=>pa===x||(x==="/"&&pa==="/index");
 document.body.insertAdjacentHTML("beforeend",`<nav class="fbt" id="fbt" aria-label="${t("Secciones")}">${T.map(x=>`<a href="${x[0]}"${soon.includes(x[0])?" data-soon":""}${on(x[0])?' class="on"':""} aria-label="${t(x[2])}">${ic(x[1])}</a>`).join("")}<a href="/perfil"${pa==="/perfil"||pa.startsWith("/u/")?' class="on"':""} aria-label="${t("Mi perfil")}">${skin(U.skin,U.name)}</a></nav>`)}
function bar(){fbNav();const da=$("#drauth");if(da)da.innerHTML=U?`<a class="out" href="#" onclick="cd();salir();return false">${t("Cerrar sesión")}</a>`:`<a class="out" href="#" onclick="cd();login();return false">${t("Iniciar sesión")}</a>`;$("#auth").innerHTML=U?`<a class="btn s" href="/u/${encodeURIComponent(U.name)}">${ic("usuario_perfil")} ${esc(U.name.replace(/_/g," "))}</a> <button class="btn s" onclick="salir()">${t("Salir")}</button>`:""}
async function login(){await info();modal(`<h3>${t("Iniciar sesión")}</h3><p class="m" style="font-size:.85rem">${t("Usa el mismo nombre y contraseña de tu cuenta del servidor.")}</p><input id="ln" placeholder="Nombre_Apellido" autocomplete="username" autocapitalize="none" maxlength="24" aria-label="Nombre_Apellido"><input id="lp" type="password" placeholder="${t("Contraseña")}" aria-label="${t("Contraseña")}" autocomplete="current-password" maxlength="72">${INFO.turnstile?'<div id="cft" style="margin:.4rem 0"></div>':""}<div class="msg" id="lm" role="alert"></div><button class="btn p" id="lb">${t("Entrar")}</button> <button class="btn" onclick="cerrar()">${t("Cancelar")}</button>`);
 const go1=async()=>{const n=$("#ln"),p=$("#lp"),b=$("#lb");if(!need(n,n.value.trim().length>=3,t("Escribe tu nombre (mínimo 3 letras)"),"#lm")||!need(p,p.value.length>0,t("Escribe tu contraseña"),"#lm"))return;
  b.disabled=true;const r=await api("/login",{method:"POST",body:{name:n.value,password:p.value,cf:CF}});b.disabled=false;if(!r.ok){resetCaptcha("#cft");$("#lm").className="msg";return $("#lm").textContent=r.d.error||"Error"}cerrar();await init();location.href="/perfil"};
 $("#lb").onclick=go1;$("#lp").onkeydown=e=>{if(e.key==="Enter")go1()};if(INFO.turnstile)captcha("#cft")}
