function postHtml(p){(window.PS=window.PS||{})[p.id]=p;const soc=p.type!=="rules"&&p.type!=="faq";return `<article class="card post"><div class="h">${skin(p.skin,p.author)}<div><a href="/u/${encodeURIComponent(p.author)}"><b>${esc(p.author.replace(/_/g," "))}</b></a>${tagsHtml(p)}${p.type==="post"?"":`<span class="tag">${t(TIT[p.type]||"")}</span>`}<br><a class="dt" href="/p/${p.id}"><small>${fecha(p.created_at)}</small></a></div></div>${p.title?`<h3 style="margin:0">${esc(p.title)}</h3>`:""}${p.body?`<p>${esc(p.body)}</p>`:""}${mediaHtml(p)}<div class="act">${soc?`<button class="btn s${p.mine>0?" p":""}" id="l${p.id}" onclick="like(${p.id})" aria-label="Like">${ic("like")} <span>${p.likes}</span></button><button class="btn s" id="cb${p.id}" onclick="coms(${p.id})" aria-label="Comentarios">${ic("discord_comentarios")} <span>${p.comments}</span></button>`:""}<button class="btn s" onclick="compartir(${p.id})" aria-label="${t("Compartir")}" title="${t("Compartir")}">${ic("compartir_vincular")}</button>${U?.canPost?`<button class="btn s" onclick="editar(${p.id})">${t("Editar")}</button>`:""}${U&&(U.canPost||((p.type==="post"||p.type==="story")&&p.author===U.name))?`<button class="btn s" onclick="borrar(${p.id})">${t("Eliminar")}</button>`:""}</div><div id="c${p.id}"></div></article>`}
function compartir(id){const p=PS[id]||{},u=location.origin+"/p/"+id;if(navigator.share)return navigator.share({title:p.title,text:p.title,url:u}).catch(()=>{});navigator.clipboard.writeText(u).then(()=>toast(t("Enlace copiado")),()=>{})}
async function like(id){if(!U)return login();const r=await api("/posts/"+id+"/like",{method:"POST",body:{}});if(!r.ok)return;const b=$("#l"+id);b.classList.toggle("p",r.d.liked);b.querySelector("span").textContent=r.d.likes}
